// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    W_WALLET c;
    function setUp() public { c = new W_WALLET(address(new Log())); }

    function testFuzz_property(uint256 pastTime, uint256 amount, address actor) public {
        vm.assume(amount <= VALUE_CAP);
        vm.warp(1_000_000_000);
        vm.assume(actor != address(c) && actor != address(0));
        vm.assume(pastTime < block.timestamp);
        amount = bound(amount, 1 ether, 1000 ether);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(pastTime);

        // immediate withdrawal attempt at the same timestamp
        vm.prank(actor);
        c.Collect(amount);

        assertTrue(address(c).balance >= c.MinSum());
    }
}
